/// Turns the [WireModel] into Dart source: one library with one part per
/// schema file.
library;

import 'analyzer.dart';
import 'config.dart';
import 'model.dart';
import 'naming.dart';

/// The generated files, by file name, in a stable order.
typedef GeneratedFiles = Map<String, String>;

/// Generated file names start with this.
const libraryStem = 'ahp_types';

/// Dart member names a field may not take.
const _reservedMembers = {
  'hashCode',
  'runtimeType',
  'toString',
  'toJson',
  'copyWith',
  'noSuchMethod',
  'other',
};

/// Emits [model] as a Dart library for [config].
GeneratedFiles emit(WireModel model, GeneratorConfig config) =>
    _Emitter(model, config).run();

/// A Dart string literal for [value], or the value itself for numbers and
/// booleans.
String literal(Object value) {
  if (value is! String) return '$value';
  final escaped = value
      .replaceAll(r'\', r'\\')
      .replaceAll("'", r"\'")
      .replaceAll(r'$', r'\$')
      .replaceAll('\n', r'\n');
  return "'$escaped'";
}

final class _Emitter {
  _Emitter(this.model, this.config);

  final WireModel model;
  final GeneratorConfig config;

  GeneratedFiles run() {
    final parts = <String, StringBuffer>{};
    for (final decl in model.decls.values) {
      final buffer = parts.putIfAbsent(decl.part, StringBuffer.new);
      buffer
        ..writeln()
        ..writeln(switch (decl) {
          ClassDecl() => _class(decl),
          EnumDecl() => _enum(decl),
          UnionDecl() => _union(decl),
          WrapperDecl() => _wrapper(decl),
        });
      if (decl is UnionDecl && decl.hasUnknown) {
        buffer
          ..writeln()
          ..writeln(_unknown(decl));
      }
    }
    final stems = [
      for (final s in config.sources)
        if (parts.containsKey(s)) s,
    ];
    final files = <String, String>{'$libraryStem.dart': _library(stems)};
    for (final stem in stems) {
      files['${libraryStem}_$stem.dart'] =
          '$_header\npart of \'$libraryStem.dart\';\n${parts[stem]}';
    }
    return files;
  }

  String get _header =>
      '// GENERATED CODE - DO NOT MODIFY BY HAND.\n'
      '// Generated by packages/ahp_wire_gen from the AHP '
      '${config.protocolVersion} JSON Schemas; run `just codegen`.\n'
      '// ignore_for_file: unintended_html_in_doc_comment\n';

  String _library(List<String> stems) {
    final b = StringBuffer()
      ..writeln(_header)
      ..writeln(
        '/// Wire types of the Agent Host Protocol '
        '${config.protocolVersion}, generated from its JSON Schemas.',
      )
      ..writeln('///')
      ..writeln(
        '/// Objects are immutable classes with `fromJson`, `toJson`, '
        '`copyWith`',
      )
      ..writeln(
        '/// and value equality. A `oneOf` is a sealed class: tagged '
        'unions decode',
      )
      ..writeln(
        '/// by their discriminator and fall back to a `…Unknown` '
        'member for values',
      )
      ..writeln(
        '/// this version does not know; string enums fall back to '
        '`\$unknown`.',
      )
      ..writeln('library;')
      ..writeln()
      ..writeln("import 'package:collection/collection.dart';")
      ..writeln("import 'package:meta/meta.dart';")
      ..writeln()
      ..writeln("import '${config.statusImport}';")
      ..writeln();
    for (final stem in stems) {
      b.writeln("part '${libraryStem}_$stem.dart';");
    }
    b
      ..writeln()
      ..writeln('/// The protocol version these types were generated from.')
      ..writeln("const wireProtocolVersion = '${config.protocolVersion}';")
      ..writeln()
      ..writeln('/// A JSON object as decoded from the wire.')
      ..writeln('typedef JsonMap = Map<String, Object?>;')
      ..writeln()
      ..writeln('/// Marks a `copyWith` argument that was not passed.')
      ..writeln('const _unset = _Unset();')
      ..writeln()
      ..writeln('final class _Unset {')
      ..writeln('  const _Unset();')
      ..writeln('}')
      ..writeln()
      ..writeln('const _deep = DeepCollectionEquality();');
    return b.toString();
  }

  String _doc(String? text, String fallback, [String indent = '']) =>
      docComment(
        text,
        fallback: fallback,
        indent: indent,
        isType: model.isType,
      );

  // Types --------------------------------------------------------------------

  String _type(TypeRef t) => switch (t) {
    PrimType(prim: Prim.string) => 'String',
    PrimType(prim: Prim.int) => 'int',
    PrimType(prim: Prim.num) => 'num',
    PrimType(prim: Prim.bool) => 'bool',
    PrimType(prim: Prim.any) => 'Object?',
    JsonMapType() => 'JsonMap',
    StatusType() => 'SessionStatus',
    ListType(:final item) => 'List<${_type(item)}>',
    MapType(:final value) => 'Map<String, ${_type(value)}>',
    NamedType(:final name) => name,
  };

  String _nullable(TypeRef t) {
    final type = _type(t);
    return type.endsWith('?') ? type : '$type?';
  }

  bool _deepEquality(TypeRef t) =>
      t is ListType ||
      t is MapType ||
      t is JsonMapType ||
      t == const PrimType(Prim.any);

  /// Whether `fromJson` of [name] takes `Object?` rather than a map.
  bool _takesAnyJson(String name) => switch (model.decls[name]) {
    EnumDecl() => true,
    UnionDecl(:final discriminator) => discriminator == null,
    _ => false,
  };

  String _decode(TypeRef t, String e, [int depth = 0]) {
    final v = 'e$depth';
    return switch (t) {
      PrimType(prim: Prim.string) => '($e as String)',
      PrimType(prim: Prim.int) => '($e as num).toInt()',
      PrimType(prim: Prim.num) => '($e as num)',
      PrimType(prim: Prim.bool) => '($e as bool)',
      PrimType(prim: Prim.any) => e,
      JsonMapType() => '($e as JsonMap)',
      StatusType() => 'SessionStatus(($e as num).toInt())',
      ListType(:final item) =>
        '[for (final $v in $e as List<Object?>) ${_decode(item, v, depth + 1)}]',
      MapType(:final value) =>
        '{for (final $v in ($e as JsonMap).entries) '
            '$v.key: ${_decode(value, '$v.value', depth + 1)}}',
      NamedType(:final name) =>
        _takesAnyJson(name)
            ? '$name.fromJson($e)'
            : '$name.fromJson($e as JsonMap)',
    };
  }

  bool _encodesAsIs(TypeRef t) => switch (t) {
    PrimType() || JsonMapType() => true,
    ListType(:final item) => _encodesAsIs(item),
    MapType(:final value) => _encodesAsIs(value),
    _ => false,
  };

  String _encode(TypeRef t, String e, [int depth = 0]) {
    if (_encodesAsIs(t)) return e;
    final v = 'e$depth';
    return switch (t) {
      StatusType() => '$e.bits',
      ListType(:final item) =>
        '[for (final $v in $e) ${_encode(item, v, depth + 1)}]',
      MapType(:final value) =>
        '{for (final $v in $e.entries) $v.key: ${_encode(value, '$v.value', depth + 1)}}',
      NamedType() => '$e.toJson()',
      _ => e,
    };
  }

  // Members inherited from unions ----------------------------------------

  /// Names of the getters the unions of [decl] declare (transitively).
  Set<String> _inherited(Decl decl) => {
    for (final u in decl.unions)
      if (model.decls[u] case final UnionDecl union) ...[
        ?union.discriminatorName,
        ...union.commonFields.map((f) => f.name),
        ..._inherited(union),
      ],
  };

  String _implements(Decl decl) =>
      decl.unions.isEmpty ? '' : ' implements ${decl.unions.join(', ')}';

  String _override(Set<String> inherited, String name) =>
      inherited.contains(name) ? '  @override\n' : '';

  // Classes -------------------------------------------------------------

  void _checkNames(ClassDecl decl) {
    for (final name in [
      ...decl.fields.map((f) => f.name),
      ...decl.consts.map((c) => c.name),
    ]) {
      if (_reservedMembers.contains(name)) {
        throw UnsupportedSchemaError(
          '${decl.name}.$name',
          'reserved member name',
        );
      }
    }
  }

  String _class(ClassDecl d) {
    _checkNames(d);
    final name = d.name;
    final inherited = _inherited(d);
    final hasUnion = d.unions.isNotEmpty;
    final b = StringBuffer()
      ..writeln(_doc(d.doc, '`$name`.'))
      ..writeln('@immutable')
      ..writeln('final class $name${_implements(d)} {')
      ..writeln('  /// Creates a [$name].');
    if (d.fields.isEmpty) {
      b
        ..writeln('  const $name();')
        ..writeln()
        ..writeln('  /// Decodes a [$name] from JSON.')
        ..writeln('  factory $name.fromJson(JsonMap json) => const $name();');
    } else {
      b.writeln('  const $name({');
      for (final f in d.fields) {
        b.writeln('    ${f.required ? 'required ' : ''}this.${f.name},');
      }
      b
        ..writeln('  });')
        ..writeln()
        ..writeln('  /// Decodes a [$name] from JSON.')
        ..writeln('  factory $name.fromJson(JsonMap json) => $name(');
      for (final f in d.fields) {
        b.writeln('    ${f.name}: ${_decodeField(f)},');
      }
      b.writeln('  );');
    }
    for (final f in d.fields) {
      b
        ..writeln()
        ..writeln(_doc(f.doc, '`${f.jsonName}`.', '  '))
        ..write(_override(inherited, f.name))
        ..writeln(
          '  final ${f.required ? _type(f.type) : _nullable(f.type)} ${f.name};',
        );
    }
    for (final c in d.consts) {
      final type = c.value is String
          ? 'String'
          : c.value is bool
          ? 'bool'
          : 'num';
      b
        ..writeln()
        ..writeln(
          _doc(
            c.doc,
            'Always ${c.value is String ? '`${c.value}`' : c.value}.',
            '  ',
          ),
        )
        ..write(_override(inherited, c.name))
        ..writeln('  $type get ${c.name} => ${literal(c.value)};');
    }
    if (d.fields.isNotEmpty) _copyWith(b, d);
    b
      ..writeln()
      ..writeln('  /// Encodes this [$name] as JSON.')
      ..write(hasUnion ? '  @override\n' : '')
      ..writeln('  JsonMap toJson() => {');
    for (final c in d.consts) {
      b.writeln('    ${literal(c.jsonName)}: ${literal(c.value)},');
    }
    for (final f in d.fields) {
      final key = literal(f.jsonName);
      if (f.required) {
        b.writeln('    $key: ${_encode(f.type, f.name)},');
      } else if (_encodesAsIs(f.type)) {
        b.writeln('    $key: ?${f.name},');
      } else {
        b.writeln(
          '    if (${f.name} case final v?) $key: ${_encode(f.type, 'v')},',
        );
      }
    }
    b.writeln('  };');
    _equality(b, name, d.fields.map((f) => (f.name, f.type)).toList());
    b.writeln('}');
    return b.toString();
  }

  String _decodeField(FieldDecl f) {
    final raw = 'json[${literal(f.jsonName)}]';
    if (f.type == const PrimType(Prim.any)) return raw;
    final decoded = _decode(f.type, raw);
    if (!f.required) return '$raw == null ? null : $decoded';
    // Hosts may leave out empty collections the schema requires.
    return switch (f.type) {
      ListType(:final item) =>
        '$raw == null ? const <${_type(item)}>[] : $decoded',
      MapType(:final value) =>
        '$raw == null ? const <String, ${_type(value)}>{} : $decoded',
      JsonMapType() => '$raw == null ? const <String, Object?>{} : $decoded',
      _ => decoded,
    };
  }

  void _copyWith(StringBuffer b, ClassDecl d) {
    final name = d.name;
    final typed = d.fields
        .map((f) => '${_nullable(f.type)} ${f.name}')
        .join(', ');
    b
      ..writeln()
      ..writeln(
        '  /// Returns a copy with the given fields replaced. Passing null clears',
      )
      ..writeln('  /// an optional field and keeps a required one.')
      ..writeln('  $name Function({$typed}) get copyWith => _copyWith;')
      ..writeln()
      ..writeln('  $name _copyWith({');
    for (final f in d.fields) {
      b.writeln(
        f.required
            ? '    ${_nullable(f.type)} ${f.name},'
            : '    Object? ${f.name} = _unset,',
      );
    }
    b.writeln('  }) => $name(');
    for (final f in d.fields) {
      final n = f.name;
      if (f.required) {
        b.writeln('    $n: $n ?? this.$n,');
      } else if (f.type == const PrimType(Prim.any)) {
        b.writeln('    $n: identical($n, _unset) ? this.$n : $n,');
      } else {
        b.writeln(
          '    $n: identical($n, _unset) ? this.$n : $n as ${_nullable(f.type)},',
        );
      }
    }
    b.writeln('  );');
  }

  void _equality(StringBuffer b, String name, List<(String, TypeRef)> fields) {
    b
      ..writeln()
      ..writeln('  @override')
      ..write(
        '  bool operator ==(Object other) =>\n      identical(this, other) || other is $name',
      );
    for (final (n, t) in fields) {
      b.write(
        _deepEquality(t)
            ? ' && _deep.equals($n, other.$n)'
            : ' && $n == other.$n',
      );
    }
    b
      ..writeln(';')
      ..writeln()
      ..writeln('  @override');
    if (fields.isEmpty) {
      b.writeln('  int get hashCode => runtimeType.hashCode;');
    } else {
      final hashes = [
        'runtimeType',
        for (final (n, t) in fields) _deepEquality(t) ? '_deep.hash($n)' : n,
      ];
      b.writeln(
        '  int get hashCode => Object.hashAll([${hashes.join(', ')}]);',
      );
    }
    final shown = fields.map((f) => '${f.$1}: \$${f.$1}').join(', ');
    b
      ..writeln()
      ..writeln('  @override')
      ..writeln("  String toString() => '$name($shown)';");
  }

  // Enums ---------------------------------------------------------------

  String _enum(EnumDecl d) {
    final b = StringBuffer()
      ..writeln(_doc(d.doc, '`${d.name}`.'))
      ..writeln('enum ${d.name} {');
    final used = <String>{};
    for (final value in d.values) {
      var id = camelCase(value);
      if (dartReservedWords.contains(id) ||
          const {
            'values',
            'index',
            'name',
            'wireValue',
            'toJson',
            'hashCode',
          }.contains(id)) {
        id = '${id}Value';
      }
      if (!used.add(id)) {
        throw UnsupportedSchemaError(
          '${d.name}.$value',
          'duplicate enum name $id',
        );
      }
      b
        ..writeln('  /// `$value`.')
        ..writeln('  $id(${literal(value)}),')
        ..writeln();
    }
    b
      ..writeln('  /// A value this client version does not know.')
      ..writeln("  \$unknown('');")
      ..writeln()
      ..writeln('  const ${d.name}(this.wireValue);')
      ..writeln()
      ..writeln(
        '  /// Decodes a [${d.name}]; values this version does not know decode to',
      )
      ..writeln('  /// [\$unknown].')
      ..writeln(
        '  factory ${d.name}.fromJson(Object? json) => values.firstWhere(',
      )
      ..writeln('    (v) => v != \$unknown && v.wireValue == json,')
      ..writeln('    orElse: () => \$unknown,')
      ..writeln('  );')
      ..writeln()
      ..writeln('  /// The JSON value.')
      ..writeln('  final String wireValue;')
      ..writeln()
      ..writeln('  /// Encodes this as JSON.')
      ..writeln('  String toJson() => wireValue;')
      ..writeln('}');
    return b.toString();
  }

  // Unions --------------------------------------------------------------

  String _union(UnionDecl d) {
    final name = d.name;
    final inherited = _inherited(d);
    final b = StringBuffer()
      ..writeln(_doc(d.doc, '`$name`.'))
      ..writeln('sealed class $name${_implements(d)} {');
    final disc = d.discriminator;
    if (disc == null) {
      _shapeFactory(b, d);
    } else {
      b
        ..writeln('  /// Decodes a [$name] from JSON by its `$disc`.')
        ..writeln(
          '  factory $name.fromJson(JsonMap json) => switch (json[${literal(disc)}]) {',
        );
      for (final c in d.cases) {
        b.writeln(
          '    ${c.values.map(literal).join(' || ')} => ${c.member}.fromJson(json),',
        );
      }
      b
        ..writeln(
          d.hasUnknown
              ? '    _ => ${d.unknownName}.fromJson(json),'
              : "    _ => throw FormatException('Invalid $name: \${json[${literal(disc)}]}'),",
        )
        ..writeln('  };');
      final discName = d.discriminatorName!;
      final values = d.cases.expand((c) => c.values).map(literal).join(', ');
      b
        ..writeln()
        ..writeln(
          '  /// The `$disc` values this version decodes to a known member.',
        )
        ..writeln(
          '  static const discriminatorValues = <${d.discriminatorType}>{$values};',
        )
        ..writeln()
        ..writeln('  /// The `$disc` discriminator.')
        ..write(_override(inherited, discName))
        ..writeln('  ${d.discriminatorType} get $discName;');
    }
    for (final f in d.commonFields) {
      b
        ..writeln()
        ..writeln(_doc(f.doc, '`${f.jsonName}`.', '  '))
        ..write(_override(inherited, f.name))
        ..writeln(
          '  ${f.required ? _type(f.type) : _nullable(f.type)} get ${f.name};',
        );
    }
    b
      ..writeln()
      ..writeln('  /// Encodes this as JSON.')
      ..write(d.unions.isEmpty ? '' : '  @override\n')
      ..writeln('  ${disc == null ? 'Object?' : 'JsonMap'} toJson();')
      ..writeln('}');
    return b.toString();
  }

  void _shapeFactory(StringBuffer b, UnionDecl d) {
    b
      ..writeln('  /// Decodes a [${d.name}] by the JSON value type.')
      ..writeln(
        '  factory ${d.name}.fromJson(Object? json) => switch (json) {',
      );
    for (final member in d.members) {
      final decl = model.decls[member]!;
      if (decl is WrapperDecl) {
        b.writeln(
          '    final ${_type(PrimType(decl.prim))} value => $member(value),',
        );
      } else {
        b.writeln('    final JsonMap value => $member.fromJson(value),');
      }
    }
    b
      ..writeln("    _ => throw FormatException('Invalid ${d.name}: \$json'),")
      ..writeln('  };');
  }

  String _wrapper(WrapperDecl d) {
    final type = _type(PrimType(d.prim));
    final b = StringBuffer()
      ..writeln(_doc(d.doc, '`${d.name}`.'))
      ..writeln('@immutable')
      ..writeln('final class ${d.name}${_implements(d)} {')
      ..writeln('  /// Creates a [${d.name}].')
      ..writeln('  const ${d.name}(this.value);')
      ..writeln()
      ..writeln('  /// The value.')
      ..writeln('  final $type value;')
      ..writeln()
      ..writeln('  @override')
      ..writeln('  $type toJson() => value;');
    _equality(b, d.name, [('value', PrimType(d.prim))]);
    b.writeln('}');
    return b.toString();
  }

  /// All discriminators of [d] and its ancestors, as (json, dart, type).
  List<(String, String, String)> _discriminators(UnionDecl d) => [
    if (d.discriminator != null)
      (d.discriminator!, d.discriminatorName!, d.discriminatorType),
    for (final u in d.unions)
      if (model.decls[u] case final UnionDecl parent)
        ..._discriminators(parent),
  ];

  String _unknown(UnionDecl d) {
    final name = d.unknownName;
    final discriminators = {for (final x in _discriminators(d)) x.$2: x}.values
        .toList();
    final b = StringBuffer()
      ..writeln(
        '/// A [${d.name}] whose `${d.discriminator}` this client version does not',
      )
      ..writeln('/// know. [json] keeps the value as received.')
      ..writeln('@immutable')
      ..writeln('final class $name implements ${d.name} {')
      ..writeln('  /// Decodes a [$name], keeping [json].')
      ..write('  $name.fromJson(this.json)');
    final inits = [
      for (final (j, n, t) in discriminators)
        t == 'bool'
            ? '$n = json[${literal(j)}] == true'
            : "$n = '\${json[${literal(j)}]}'",
      for (final f in d.commonFields) '${f.name} = ${_decodeField(f)}',
    ];
    b
      ..writeln(inits.isEmpty ? ';' : '\n      : ${inits.join(',\n        ')};')
      ..writeln()
      ..writeln('  /// The JSON value as received.')
      ..writeln('  final JsonMap json;');
    for (final (_, n, t) in discriminators) {
      b
        ..writeln()
        ..writeln('  @override')
        ..writeln('  final $t $n;');
    }
    for (final f in d.commonFields) {
      b
        ..writeln()
        ..writeln('  @override')
        ..writeln(
          '  final ${f.required ? _type(f.type) : _nullable(f.type)} ${f.name};',
        );
    }
    b
      ..writeln()
      ..writeln('  @override')
      ..writeln('  JsonMap toJson() => json;');
    _equality(b, name, [('json', const JsonMapType())]);
    b.writeln('}');
    return b.toString();
  }
}
